import subprocess

WORDLIST = "/usr/share/wordlists/rockyou.txt"
EXECUTABLE = "./rockyou"

def brute_force():
    try:
        with open(WORDLIST, "r", encoding="latin-1") as file:
            for password in file:
                password = password.strip()
                print(f"Trying: {password}")

                # Run the executable and provide the password as input
                process = subprocess.run(
                    [EXECUTABLE], input=password, text=True, capture_output=True
                )

                # Check exit status to determine success
                if process.returncode == 0:
                    print(f"Password found: {password}")
                    return

        print("Password not found in wordlist.")
    except FileNotFoundError:
        print(f"File not found: {WORDLIST}")
    except PermissionError:
        print(f"Permission denied: {WORDLIST}")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    brute_force()
